$raw = get_option("auhfc_settings_sitewide");
$blob = is_string($raw) ? $raw : wp_json_encode($raw);
echo "sitewide_len=", strlen($blob), "\n";
echo (str_contains($blob, "imc-calc-submit") ? "sitewide_has_js\n" : "sitewide_no_js\n");
$article = get_option("auhfc_settings_article");
$ablob = is_string($article) ? $article : wp_json_encode($article);
echo "article_opt_len=", strlen($ablob), "\n";
foreach (array(12,21,25,32) as $id) {
  $all = get_post_meta($id);
  foreach ($all as $k => $vals) {
    $v = implode(" ", $vals);
    if (str_contains($v, "imc-calc") || str_contains($k, "auhfc") || str_contains($k, "hfc")) {
      echo $id, " ", $k, " len=", strlen($v), " has_submit=", str_contains($v, "imc-calc-submit") ? "yes" : "no", "\n";
    }
  }
}
